import{_ as i,o as a,c as e,a as n}from"./app.DkoUFz-u.js";const p=JSON.parse('{"title":"AI技术学习笔记：Gemini系列模型","description":"","frontmatter":{},"headers":[],"relativePath":"ai/models/international/gemini.md","filePath":"ai/models/international/gemini.md"}'),r={name:"ai/models/international/gemini.md"};function d(o,t,l,h,s,m){return a(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="ai技术学习笔记-gemini系列模型" tabindex="-1">AI技术学习笔记：Gemini系列模型 <a class="header-anchor" href="#ai技术学习笔记-gemini系列模型" aria-label="Permalink to &quot;AI技术学习笔记：Gemini系列模型&quot;">​</a></h1><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p>Gemini是谷歌DeepMind团队开发的原生多模态大语言模型家族，于2023年12月6日正式发布。作为谷歌对抗OpenAI的GPT系列和Anthropic的Claude系列的核心力量，Gemini的诞生标志着谷歌将旗下两个顶级AI研究团队——Google Brain与DeepMind——合并后的首次重大成果亮相。截至2026年5月，Gemini App月活跃用户数已从2025年I/O大会时的4亿增长至超过9亿，旗下已有13款产品用户规模超10亿，其中5款产品用户数突破30亿。</p><p>Gemini的核心技术理念是 <strong>“原生多模态”</strong> ——从一开始就设计为能够无缝理解、处理和生成文本、图像、音频、视频等多种信息形式，而非像某些竞争模型那样将不同模态的处理能力“拼接”起来。这一设计哲学贯穿了Gemini整个发展历程，并持续演进至今。在2026年I/O大会上，谷歌进一步明确提出将Gemini从一个聊天机器人升级为覆盖搜索、办公、开发、视频和移动生态的 <strong>“AI操作系统”</strong> 。</p><p><strong>命名体系</strong>：Gemini系列早期采用“Ultra / Pro / Nano”三档命名——Ultra代表旗舰性能、Pro代表均衡能力、Nano代表端侧轻量；自3.0版本起，谷歌过渡至“Pro / Flash / Nano”架构，对应通用高性能与轻量快速两大方向；到3.5版本，“Pro”与“Flash”正式成为主力双线——Pro定位旗舰级推理，Flash主打极致速度与智能体任务优化。</p><h2 id="二、发展历程" tabindex="-1">二、发展历程 <a class="header-anchor" href="#二、发展历程" aria-label="Permalink to &quot;二、发展历程&quot;">​</a></h2><h3 id="_2-1-奠基阶段-2023—2024-从gemini-1-0到1-5" tabindex="-1">2.1 奠基阶段（2023—2024）：从Gemini 1.0到1.5 <a class="header-anchor" href="#_2-1-奠基阶段-2023—2024-从gemini-1-0到1-5" aria-label="Permalink to &quot;2.1 奠基阶段（2023—2024）：从Gemini 1.0到1.5&quot;">​</a></h3><p><strong>Gemini 1.0</strong>（2023年12月6日）是谷歌合并Google Brain与DeepMind后发布的首个大模型，首次展示原生多模态能力。初期面向开发者开放API支持。</p><p><strong>Gemini 1.5</strong>（2024年2月）在上下文窗口上实现重大突破，首次支持<strong>100万token</strong>的超长上下文（相当于约75万单词），可一次性处理《指环王》系列全集。同年4月，1.5 Pro加入“音频理解”能力并全面开放。1.5 Flash则主打轻量化、低延迟与低成本的平衡。Gemini 1.5系列是首个正式商用的百万token级模型，主要应用包括长篇文档分析、完整代码库处理等场景，同时支持函数调用、JSON模式、嵌入等API特性。</p><h3 id="_2-2-加速迭代阶段-2025年上半年-gemini-2-0的全面铺开" tabindex="-1">2.2 加速迭代阶段（2025年上半年）：Gemini 2.0的全面铺开 <a class="header-anchor" href="#_2-2-加速迭代阶段-2025年上半年-gemini-2-0的全面铺开" aria-label="Permalink to &quot;2.2 加速迭代阶段（2025年上半年）：Gemini 2.0的全面铺开&quot;">​</a></h3><p>2025年2月，谷歌发布<strong>Gemini 2.0“全家桶”</strong> ，包括2.0 Pro（实验版）、2.0 Flash和2.0 Flash-Lite三款模型。2.0 Flash Thinking实验模型——谷歌首个推理模型——能够将提示分解为一系列思考步骤，并展示其推导过程，用户可追踪模型的推理逻辑。这些模型均支持上下文窗口100万—200万token，展现了强大的多模态推理能力。</p><p>2025年3月，<strong>Gemini 2.5 Pro</strong>发布，内置“思考链”机制提升推理能力，在SWE-Bench Verified评估中得分63.8%，训练数据截止至2025年1月。支持Google搜索集成以验证事实准确性，在实际应用中可接入实时信息。</p><p>2025年6月，Gemini 2.5系列全系开放商用，其中轻量级模型Flash-Lite以0.1美元/百万Token（约人民币0.7元）的定价大幅拉低了大模型推理成本。</p><h3 id="_2-3-智能体与推理深化阶段-2025年下半年-3-0系列亮相" tabindex="-1">2.3 智能体与推理深化阶段（2025年下半年）：3.0系列亮相 <a class="header-anchor" href="#_2-3-智能体与推理深化阶段-2025年下半年-3-0系列亮相" aria-label="Permalink to &quot;2.3 智能体与推理深化阶段（2025年下半年）：3.0系列亮相&quot;">​</a></h3><p>2025年8月，谷歌I/O大会预热阶段透露Gemini 3.0项目的开发进度。同年12月，Gemini 3.0 Flash正式发布，被定位为首款“轻量级智能体模型”，引入三层思考模式（无/轻/深），标志着Flash系列从“轻量回答”全面转向“智能体任务执行”。2.0 Pro实验版同步更名为3.0 Pro，引入分层推理能力。</p><p>2025年10月，谷歌推出基于Gemini 2.5 Pro的“计算机使用”模型——新增computer_use工具，赋予AI智能体与图形用户界面直接交互的能力，可通过点击、打字、滚动等操作自主完成跨应用任务。</p><h3 id="_2-4-架构深化阶段-2026年上半年-3-1系列的精细化扩展" tabindex="-1">2.4 架构深化阶段（2026年上半年）：3.1系列的精细化扩展 <a class="header-anchor" href="#_2-4-架构深化阶段-2026年上半年-3-1系列的精细化扩展" aria-label="Permalink to &quot;2.4 架构深化阶段（2026年上半年）：3.1系列的精细化扩展&quot;">​</a></h3><p>2026年2月19日，谷歌发布<strong>Gemini 3.1 Pro</strong>，这是首次以“.1”作为版本增量发布的Gemini模型，基于Gemini 3 Deep Think的技术基础进一步提升核心推理能力，在ARC-AGI-2基准测试中取得77.1%的得分。</p><p>2026年3月4日，<strong>Gemini 3.1 Flash-Lite</strong>正式推出，主打速度与成本效益，首Token响应速度较前代提升2.5倍，吞吐量可达每秒363个Token。</p><p>2026年3月27日，<strong>Gemini 3.1 Flash Live</strong>发布，专为低延迟实时音频与语音交互设计，在ComplexFuncBench Audio测试中取得约90.8%的成绩。</p><h3 id="_2-5-全模态与智能体生态爆发阶段-2026年5月i-o大会" tabindex="-1">2.5 全模态与智能体生态爆发阶段（2026年5月I/O大会） <a class="header-anchor" href="#_2-5-全模态与智能体生态爆发阶段-2026年5月i-o大会" aria-label="Permalink to &quot;2.5 全模态与智能体生态爆发阶段（2026年5月I/O大会）&quot;">​</a></h3><p>2026年5月19日，谷歌在年度开发者大会Google I/O 2026上发布了一系列重磅更新，标志着Gemini正式从“聊天机器人”升级为 <strong>“AI操作系统”</strong> ：</p><ul><li><strong>Gemini 3.5 Flash</strong>：即日起面向全球数十亿用户免费开放，成为Gemini App和谷歌搜索“AI模式”的默认模型，专为快速高效任务与智能体场景深度优化，输出速度达每秒289 tokens，是Claude Opus 4.7和GPT-5.5的约4倍。</li><li><strong>Gemini 3.5 Pro</strong>：同期披露进入谷歌内部使用阶段，预计6月正式发布。</li><li><strong>Gemini Omni</strong>：全新的全模态世界模型，支持视频、图像、音频、文本任意组合输入，具备对话式多轮视频编辑与物理规律理解能力。</li></ul><p>同日，谷歌发布了执行全程超过30小时长任务、7×24小时运行的 <strong>Gemini Spark个人智能体</strong>，以及面向开发者管理AI智能体集群的 <strong>Antigravity 2.0平台</strong>。谷歌搜索迎来25年来最大改版，新搜索框支持多模态输入和连续对话，标志着搜索正式从“链接列表”进入“搜索助手”时代。</p><p>谷歌还同时调整了定价模式，推出面向开发者的100美元/月Ultra基础版方案，最高阶Ultra旗舰版月费从250美元降至200美元。</p><h3 id="_2-6-gemini系列主要版本汇总" tabindex="-1">2.6 Gemini系列主要版本汇总 <a class="header-anchor" href="#_2-6-gemini系列主要版本汇总" aria-label="Permalink to &quot;2.6 Gemini系列主要版本汇总&quot;">​</a></h3><table tabindex="0"><thead><tr><th>版本</th><th>发布时间</th><th>核心特点</th></tr></thead><tbody><tr><td>Gemini 1.0</td><td>2023年12月</td><td>原生多模态，Pro/Nano/Ultra三档</td></tr><tr><td>Gemini 1.5</td><td>2024年2月</td><td>百万token上下文窗口首秀</td></tr><tr><td>Gemini 2.0 Flash/Pro</td><td>2025年2月</td><td>2.0 Flash Thinking推理模型，2.0 Pro 200万上下文</td></tr><tr><td>Gemini 2.5 Pro</td><td>2025年3月</td><td>思考链推理，SWE-Bench 63.8%</td></tr><tr><td>Gemini 3.0 Flash/Pro</td><td>2025年12月</td><td>首款轻量智能体模型，三层思考模式</td></tr><tr><td>Gemini 3.1 Pro</td><td>2026年2月</td><td>ARC-AGI-2 77.1%，200万token</td></tr><tr><td>Gemini 3.1 Flash-Lite</td><td>2026年3月</td><td>首Token速度提升2.5倍，363 tokens/秒吞吐量</td></tr><tr><td>Gemini 3.1 Flash Live</td><td>2026年3月</td><td>低延迟音频实时交互，90.8%准确率</td></tr><tr><td>Gemini 3.5 Flash</td><td>2026年5月</td><td>输出速度289 tokens/秒，智能体与编程旗舰</td></tr><tr><td>Gemini Omni Flash</td><td>2026年5月</td><td>全模态视频生成与对话式编辑，物理世界理解</td></tr></tbody></table><h2 id="三、核心技术" tabindex="-1">三、核心技术 <a class="header-anchor" href="#三、核心技术" aria-label="Permalink to &quot;三、核心技术&quot;">​</a></h2><h3 id="_3-1-原生多模态架构" tabindex="-1">3.1 原生多模态架构 <a class="header-anchor" href="#_3-1-原生多模态架构" aria-label="Permalink to &quot;3.1 原生多模态架构&quot;">​</a></h3><p>与GPT和Claude采用“后期融合”方式不同——先各自训练独立的文本模型、图像模型再将能力拼接——Gemini从模型设计之初便采用 <strong>“原生多模态”</strong> （natively multimodal）训练范式。简单来说，Gemini从一开始就在文本、图像、音频、视频等多模态数据上进行端到端的联合训练，使模型能够像人类一样综合理解跨模态内容，而非在不同模态之间“翻译”。在技术实现层面，Gemini使用跨模态对齐编码器（共享权重与模态特定投影层结合）将不同模态数据映射至统一语义空间，配合动态模态注意力机制根据输入数据类型实时调整模态间注意力权重，并通过端到端联合训练的多任务学习框架统一优化各模态目标。</p><p>Gemini Omni Flash则将这一能力推向了新高度：基于原生多模态架构，支持将视频、图像、音频和文本进行任意组合输入，生成并编辑高质量视频，实现了物理规律理解与多轮对话逻辑的一致性。例如，它能够理解“用黏土动画解释蛋白质折叠”这样的抽象指令，并在生成过程中同时遵循科学原理和物理规律。</p><h3 id="_3-2-混合专家架构" tabindex="-1">3.2 混合专家架构 <a class="header-anchor" href="#_3-2-混合专家架构" aria-label="Permalink to &quot;3.2 混合专家架构&quot;">​</a></h3><p>Gemini 2.0 Flash系列采用<strong>改进型混合专家架构</strong>，通过动态路由机制将输入数据分配至多个专家子网络并行处理。具体而言：</p><ul><li><strong>专家专业化</strong>：每个专家子网络聚焦特定任务域（如文本生成、图像理解、代码分析），通过领域自适应训练减少参数冗余，使同等参数量下推理速度提升40%</li><li><strong>稀疏激活</strong>：以10亿参数模型为例，单次推理仅需激活约2%的参数，显著减少计算开销</li><li><strong>量化感知训练</strong>：支持模型参数压缩至4-bit精度，推理速度提升3倍</li></ul><h3 id="_3-3-超长上下文窗口" tabindex="-1">3.3 超长上下文窗口 <a class="header-anchor" href="#_3-3-超长上下文窗口" aria-label="Permalink to &quot;3.3 超长上下文窗口&quot;">​</a></h3><p>上下文窗口扩展是Gemini的核心差异化优势之一。从1.5版本的100万token，到2.0 Pro实验版的200万token，再到3.1系列全线统一为<strong>200万token</strong>，Gemini始终保持着行业领先的超长上下文能力。200万token的实际应用价值体现在：可一次性处理约2000页文本内容，涵盖完整的企业级代码库、数百页法律合同或整个《指环王》系列的多部长篇文档。</p><h3 id="_3-4-分层思考机制" tabindex="-1">3.4 分层思考机制 <a class="header-anchor" href="#_3-4-分层思考机制" aria-label="Permalink to &quot;3.4 分层思考机制&quot;">​</a></h3><p>从Gemini 3.0 Flash开始，谷歌引入<strong>三层思考模式</strong>，用户可根据任务需求控制模型推理深度，以平衡响应速度与质量：</p><table tabindex="0"><thead><tr><th>思考层级</th><th>用途</th><th>特性</th></tr></thead><tbody><tr><td>无思考模式</td><td>高频实时问答、快速响应</td><td>最低延迟，最快首Token</td></tr><tr><td>轻思考模式</td><td>日常任务执行</td><td>速度和推理质量的基本平衡</td></tr><tr><td>深度思考模式</td><td>复杂推理、多步骤任务</td><td>充分发挥模型的推理链能力</td></tr></tbody></table><p>Gemini 2.0 Flash Thinking作为谷歌首个推理模型，另一个独特功能是<strong>展示完整思考链</strong>——用户可以看到模型的假设、推理逻辑以及为何以某种方式回应的全过程，提升了AI决策的透明度和可理解性。</p><h3 id="_3-5-智能体能力" tabindex="-1">3.5 智能体能力 <a class="header-anchor" href="#_3-5-智能体能力" aria-label="Permalink to &quot;3.5 智能体能力&quot;">​</a></h3><p>从3.0 Flash开始，Gemini系列定位全面转向 <strong>“智能体模型”</strong> ，核心能力包括：</p><ul><li><strong>工具调用</strong>：原生支持函数调用、代码执行、Google搜索集成等，可自动识别所需参数并调用外部服务</li><li><strong>多步骤任务规划</strong>：在Antigravity 2.0平台上展示过自主调度93个子智能体完成从零构建操作系统内核的完整项目</li><li><strong>终端环境执行</strong>：以Gemini 3.1 Pro在Terminal-bench上70.3%的得分，代表了命令行自主执行能力</li><li><strong>跨应用操作</strong>：通过computer_use工具实现点击、打字、滚动等GUI操作，完成跨应用任务</li></ul><h3 id="_3-6-全模态物理世界理解" tabindex="-1">3.6 全模态物理世界理解 <a class="header-anchor" href="#_3-6-全模态物理世界理解" aria-label="Permalink to &quot;3.6 全模态物理世界理解&quot;">​</a></h3><p>Gemini Omni Flash在技术架构上引入了一项不同于传统视频生成模型的设计：不仅生成像素级别的画面，还尝试将<strong>物理世界的规律</strong>（重力、动能、流体动力学等）纳入生成过程。这使得模型在面对“水从高处流下”“球体下落反弹”等需要物理直觉的任务时，能产生更符合现实规律的输出。现场演示显示，Omni在对话式多轮视频编辑中具备上下文记忆能力，可在改变场景、角度或特定细节时，保持角色一致性并遵循连续的物理逻辑。</p><h2 id="四、训练方法" tabindex="-1">四、训练方法 <a class="header-anchor" href="#四、训练方法" aria-label="Permalink to &quot;四、训练方法&quot;">​</a></h2><h3 id="_4-1-预训练与多模态联合训练" tabindex="-1">4.1 预训练与多模态联合训练 <a class="header-anchor" href="#_4-1-预训练与多模态联合训练" aria-label="Permalink to &quot;4.1 预训练与多模态联合训练&quot;">​</a></h3><p>Gemini系列在大规模多模态数据集上进行预训练，数据涵盖公开网页、书籍、学术论文、代码库、图像、音频和视频等多种来源。其核心训练理念与GPT和Claude的根本性差异在于：Gemini从设计之初就将多模态理解内嵌于基础模型架构之中，而非通过后期微调添加视觉或音频能力。谷歌凭借YouTube（视频）、Google Books（书籍）、Google Images（图片）和数十亿次搜索查询记录等全球级数据资源，在多模态预训练数据数量和多样性上具有天然优势。</p><h3 id="_4-2-推理强化训练" tabindex="-1">4.2 推理强化训练 <a class="header-anchor" href="#_4-2-推理强化训练" aria-label="Permalink to &quot;4.2 推理强化训练&quot;">​</a></h3><p>从Gemini 2.0 Flash Thinking开始，谷歌引入了<strong>推理链微调</strong>——通过在训练中强化模型对复杂问题分解、逐步推导过程的建模能力，使模型能够将复杂的多步骤查询拆解为一系列可执行步骤。2.5 Pro进一步内置了结构化“思考链”机制，展示完整推理过程和处理复杂逻辑任务。</p><h3 id="_4-3-后训练与对齐" tabindex="-1">4.3 后训练与对齐 <a class="header-anchor" href="#_4-3-后训练与对齐" aria-label="Permalink to &quot;4.3 后训练与对齐&quot;">​</a></h3><p>Gemini的后训练过程包括：通过人类偏好数据和强化学习进行对齐优化；集成Google搜索工具以获取实时事实性信息进行验证；应用SynthID数字水印技术保障AI生成内容的可追溯性。谷歌强调其在网络安全方面的持续优化——Gemini 3.5 Flash经过专门的安全防护训练，使其生成有害内容的几率更低，同时也更不容易误拒安全的查询请求。</p><h3 id="_4-4-垂直整合优势" tabindex="-1">4.4 垂直整合优势 <a class="header-anchor" href="#_4-4-垂直整合优势" aria-label="Permalink to &quot;4.4 垂直整合优势&quot;">​</a></h3><p>与OpenAI和Anthropic不同，谷歌拥有完整的技术垂直整合能力：从自研TPU芯片到超大规模算力集群，从多模态大模型到终端应用，覆盖AI产业链的每一个环节。谷歌CEO皮查伊在I/O 2026大会上表示，谷歌的算力基础设施、算法积累与数据资产的融合，使Gemini能够在相同算力预算下实现更高的训练效率。</p><h2 id="五、主要版本详述" tabindex="-1">五、主要版本详述 <a class="header-anchor" href="#五、主要版本详述" aria-label="Permalink to &quot;五、主要版本详述&quot;">​</a></h2><h3 id="_5-1-gemini-3-5-flash-——-2026年的主力智能体模型" tabindex="-1">5.1 Gemini 3.5 Flash —— 2026年的主力智能体模型 <a class="header-anchor" href="#_5-1-gemini-3-5-flash-——-2026年的主力智能体模型" aria-label="Permalink to &quot;5.1 Gemini 3.5 Flash —— 2026年的主力智能体模型&quot;">​</a></h3><p>作为2026年I/O大会的核心发布，Gemini 3.5 Flash被称为谷歌“迄今为止最强大的智能体和编码模型”。它基于Gemini 3 Flash推理基础构建，在编码、工具调用、多模态理解等多项基准测试中全面超越了三个月前发布的旗舰模型Gemini 3.1 Pro。具体评测指标上，它在Terminal-bench 2.1中得分76.2%（对比GPT-5.5的78.2%）、MCP Atlas中得分83.6%、Toolathlon中得分56.5%。在Agent能力方面，Gemini 3.5 Flash专门针对自主任务拆解、实时交互、高频调用场景进行了深度优化。</p><p>目前，Gemini 3.5 Flash已成为Gemini网页版及App的默认模型，全球同步上线并向所有用户免费开放。API定价为输入$1.50/百万token、输出$9.00/百万token，与Gemini 3.1 Pro（$2.00/$12.00）相比降低了约25%。</p><p>Gemini 3.5 Flash的上下文窗口为100万token，知识截止日期为2025年1月，支持文本、图像、音频、视频和PDF等多模态输入，工具调用、代码执行、搜索集成均为原生支持。</p><h3 id="_5-2-gemini-3-1-pro-——-推理旗舰-2026年2月" tabindex="-1">5.2 Gemini 3.1 Pro —— 推理旗舰（2026年2月） <a class="header-anchor" href="#_5-2-gemini-3-1-pro-——-推理旗舰-2026年2月" aria-label="Permalink to &quot;5.2 Gemini 3.1 Pro —— 推理旗舰（2026年2月）&quot;">​</a></h3><p>Gemini 3.1 Pro是首次以“.1”作为版本增量的中间版本，在ARC-AGI-2基准测试中取得了77.1%的得分，专注于复杂推理任务。该模型采用阶梯计费模式，并在核心推理能力提升的情况下保持了与上代相同的价格。在Agent评测中，Gemini 3.1 Pro在多步骤工作流（MCP Atlas 78.2%）和UI操控（OSWorld 76.2%）领域保持领先。在谷歌的Android Bench榜单中，Gemini 3.1 Pro与GPT-5.4并列顶级AI开发模型，两者在Kotlin/Java代码生成的准确性与效率上均超过92%。</p><h3 id="_5-3-gemini-3-1-flash-lite-flash-live-——-极致速度与实时交互" tabindex="-1">5.3 Gemini 3.1 Flash-Lite &amp; Flash Live —— 极致速度与实时交互 <a class="header-anchor" href="#_5-3-gemini-3-1-flash-lite-flash-live-——-极致速度与实时交互" aria-label="Permalink to &quot;5.3 Gemini 3.1 Flash-Lite &amp; Flash Live —— 极致速度与实时交互&quot;">​</a></h3><p>Gemini 3.1 Flash-Lite发布于2026年3月，首Token响应速度较前代提升2.5倍，吞吐量可达每秒363个Token，定价为每百万输入Token 0.25美元、输出1.50美元，在Arena.ai排行榜上获得1432分。</p><p>Gemini 3.1 Flash Live发布于2026年3月27日，专为低延迟实时音频与语音交互设计，在ComplexFuncBench Audio测试中取得约90.8%的成绩。</p><h3 id="_5-4-gemini-2-5-pro-——-推理能力奠基作" tabindex="-1">5.4 Gemini 2.5 Pro —— 推理能力奠基作 <a class="header-anchor" href="#_5-4-gemini-2-5-pro-——-推理能力奠基作" aria-label="Permalink to &quot;5.4 Gemini 2.5 Pro —— 推理能力奠基作&quot;">​</a></h3><p>Gemini 2.5 Pro发布于2025年3月，是首个内置“思考链”机制的Gemini模型，在SWE-Bench Verified中得分63.8%，在Humanity‘s Last Exam基准测试中取得18.8%。API定价为每百万输入tokens 1.25美元起（超过20万tokens后升至2.50美元）、输出tokens 10美元起。2025年11月，谷歌与印度信实Jio合作，为超5亿用户免费提供Gemini 2.5 Pro模型及相关AI服务。</p><h3 id="_5-5-gemini-omni-flash-——-全模态世界模型" tabindex="-1">5.5 Gemini Omni Flash —— 全模态世界模型 <a class="header-anchor" href="#_5-5-gemini-omni-flash-——-全模态世界模型" aria-label="Permalink to &quot;5.5 Gemini Omni Flash —— 全模态世界模型&quot;">​</a></h3><p>Gemini Omni Flash于2026年5月发布，是Omni系列的首个模型。定位为谷歌最先进的全模态AI系统，支持文本、图像、音频、视频四种模态的任意组合输入与生成，目前首发版本主要聚焦视频输出，未来将逐步扩展至图片和文本领域。Omni生成的内容均带有SynthID数字水印，相关核验功能已嵌入谷歌搜索和Chrome浏览器。从会后反馈来看，业界对Omni的稳定性评价不一，有观察者认为“表现不如预期”，从演示到大规模应用的稳定性仍有待验证。</p><h2 id="六、应用与生态" tabindex="-1">六、应用与生态 <a class="header-anchor" href="#六、应用与生态" aria-label="Permalink to &quot;六、应用与生态&quot;">​</a></h2><h3 id="_6-1-产品矩阵" tabindex="-1">6.1 产品矩阵 <a class="header-anchor" href="#_6-1-产品矩阵" aria-label="Permalink to &quot;6.1 产品矩阵&quot;">​</a></h3><p>Gemini的产品生态涵盖从个人消费端到企业服务端的完整链条：</p><ul><li><strong>Gemini App</strong>：面向普通用户的对话应用，月活跃用户超9亿，默认采用3.5 Flash模型</li><li><strong>Google AI Studio</strong>：浏览器中的AI开发工作空间，支持测试Gemini模型、构建应用、生成图像视频、导出代码</li><li><strong>Vertex AI</strong>：企业级MLOps平台，通过Gemini API提供大规模企业部署</li><li><strong>Gemini API</strong>：面向开发者的程序化接口，支持多模态输入/输出、函数调用和结构化数据生成</li><li><strong>Gemini Spark</strong>：7×24小时云端运行的个人智能体，深度集成Gmail、Docs、Calendar等Google Workspace</li><li><strong>Antigravity 2.0</strong>：独立的智能体管理与开发桌面应用，可被视为一个“AI智能体操作系统”，支持多智能体编排和全生命周期管理</li><li><strong>Gemini Enterprise</strong>：企业级AI订阅服务，提供数据隔离和安全合规保障</li></ul><h3 id="_6-2-与谷歌全生态的深度集成" tabindex="-1">6.2 与谷歌全生态的深度集成 <a class="header-anchor" href="#_6-2-与谷歌全生态的深度集成" aria-label="Permalink to &quot;6.2 与谷歌全生态的深度集成&quot;">​</a></h3><p>Gemini的核心战略优势在于与谷歌全系产品的原生集成：</p><ul><li><strong>谷歌搜索</strong>：搜索框迎来25年来最大改版，支持多模态输入和连续对话。AI概览功能月活跃用户突破25亿，AI模式用户超10亿</li><li><strong>Android Studio</strong>：Gemini 3.1 Pro Preview已深度整合进Android Studio Arctic Fox，支持实时UI预览和动态代码重构</li><li><strong>YouTube</strong>：Gemini集成YouTube理解能力，支持视频内容总结和互动</li><li><strong>Google Workspace</strong>：Gmail智能回复、Google Docs内容辅助、Google Meet实时字幕均基于Gemini技术</li><li><strong>智能眼镜</strong>：谷歌与三星、Warby Parker、Gentle Monster合作推出AI眼镜，用户可通过Gemini获取实时导航、智能下单等支持</li></ul><h3 id="_6-3-api定价体系" tabindex="-1">6.3 API定价体系 <a class="header-anchor" href="#_6-3-api定价体系" aria-label="Permalink to &quot;6.3 API定价体系&quot;">​</a></h3><p>2026年4月，谷歌对Gemini API的计费档位进行了更新，新增多个推理服务档位以满足不同场景需求。以下是各版本截至2026年5月的主要定价：</p><table tabindex="0"><thead><tr><th>模型</th><th>输入（每百万token）</th><th>输出（每百万token）</th><th>适用场景</th></tr></thead><tbody><tr><td>Gemini 3.5 Flash</td><td>$1.50</td><td>$9.00</td><td>智能体任务、实时交互</td></tr><tr><td>Gemini 3.5 Flash缓存</td><td>$0.15</td><td>—</td><td>长文档/频次高的场景</td></tr><tr><td>Gemini 3.1 Pro</td><td>$2.00</td><td>$12.00</td><td>复杂推理</td></tr><tr><td>Gemini 3.1 Flash-Lite</td><td>$0.25</td><td>$1.50</td><td>大规模高吞吐量</td></tr><tr><td>Gemini 2.5 Pro</td><td>$1.25-$2.50</td><td>$10.00</td><td>基础推理任务</td></tr></tbody></table><p>各模型的延迟差异较大：需要高优先级保障、延迟控制在毫秒至秒级，建议选择Priority档位；对延迟不敏感的任务可选择Flex或Batch档位享受五折优惠。</p><h3 id="_6-4-企业应用场景" tabindex="-1">6.4 企业应用场景 <a class="header-anchor" href="#_6-4-企业应用场景" aria-label="Permalink to &quot;6.4 企业应用场景&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>典型应用</th><th>推荐模型</th></tr></thead><tbody><tr><td>软件开发</td><td>代码生成、调试、UI优化、安卓开发集成</td><td>Gemini 3.1 Pro / 3.5 Flash</td></tr><tr><td>智能体自动化</td><td>多步骤工作流、跨应用操作、智能体集群管理</td><td>Gemini 3.5 Flash / Antigravity 2.0</td></tr><tr><td>数据分析</td><td>长篇文档处理、大规模代码库分析、数据可视化</td><td>Gemini 3.1 Pro（200万token）</td></tr><tr><td>实时交互</td><td>语音助手、实时客服、实时欺诈检测</td><td>Gemini 3.1 Flash Live</td></tr><tr><td>多媒体内容创作</td><td>视频编辑、图文生成、跨模态设计</td><td>Gemini Omni Flash</td></tr><tr><td>跨境服务</td><td>低预算高并发场景、发展中国家普惠AI</td><td>Gemini 2.5 Pro（印度5亿用户免费）</td></tr></tbody></table><h3 id="_6-5-开发者与学术生态" tabindex="-1">6.5 开发者与学术生态 <a class="header-anchor" href="#_6-5-开发者与学术生态" aria-label="Permalink to &quot;6.5 开发者与学术生态&quot;">​</a></h3><ul><li><strong>Google AI Studio</strong>：2026年发展为一个全面的AI软件开发平台，支持“Vibe Coding”、多模态生成、Android应用构建和云项目部署</li><li><strong>学术界合作</strong>：2025年基于Gemini 2.5 Pro的教育系统升级版提供了智能教学规划、多媒体内容生成等30余项AI功能，覆盖美国百余所高等院校</li><li><strong>开源模型协同</strong>：谷歌同时维护了Gemma系列开源模型（参数范围20亿—270亿），开发者可根据需求微调，以每月5%的市场占有率增长</li></ul><h2 id="七、基准测试与竞争态势" tabindex="-1">七、基准测试与竞争态势 <a class="header-anchor" href="#七、基准测试与竞争态势" aria-label="Permalink to &quot;七、基准测试与竞争态势&quot;">​</a></h2><h3 id="_7-1-核心基准测试表现" tabindex="-1">7.1 核心基准测试表现 <a class="header-anchor" href="#_7-1-核心基准测试表现" aria-label="Permalink to &quot;7.1 核心基准测试表现&quot;">​</a></h3><p>Gemini各版本在权威基准测试中的得分：</p><p><strong>代码工程（SWE-Bench Verified）：</strong></p><table tabindex="0"><thead><tr><th>模型</th><th>得分</th></tr></thead><tbody><tr><td>Claude 4系列</td><td>72.7%</td></tr><tr><td>GPT-5.5</td><td>58.6%</td></tr><tr><td>Gemini 3.5 Flash</td><td>55.1%</td></tr><tr><td>Gemini 3.1 Pro</td><td>54.2%</td></tr><tr><td>Gemini 3 Flash</td><td>49.6%</td></tr><tr><td>Claude Opus 4.7</td><td>64.3%</td></tr></tbody></table><p>数据来源。Gemini 3.5 Flash在代码工程领域仍有追赶空间，Claude 4系列在SWE-bench上均超过72%，标志着代码Agent从“辅助工具”跨入“自主工程师”阶段。此前，Gemini 2.5 Pro在SWE-Bench Verified评估中得分63.8%。</p><p><strong>Agent能力（MCP Atlas &amp; OSWorld）：</strong></p><table tabindex="0"><thead><tr><th>模型</th><th>MCP Atlas</th><th>OSWorld- Verified</th></tr></thead><tbody><tr><td>Gemini 3.5 Flash</td><td>83.6%</td><td>—</td></tr><tr><td>Gemini 3.1 Pro</td><td>78.2%</td><td>76.2%</td></tr><tr><td>Claude Opus 4.7</td><td>79.1%</td><td>—</td></tr><tr><td>GPT-5.5</td><td>75.3%</td><td>—</td></tr></tbody></table><p>数据来源。Gemini在多步骤工作流和UI操控领域保持领先地位。Gemini 3.1 Pro在OSWorld- Verified中能独立完成约四分之三的真实日常桌面任务。</p><p><strong>安卓开发（Android Bench）：</strong></p><p>2026年4月，谷歌的Android Bench榜单显示，OpenAI的GPT-5.4与谷歌Gemini 3.1 Pro Preview并列顶级AI开发模型，两者在Kotlin和Java代码生成、调试、UI优化等维度得分均超过92%。</p><h3 id="_7-2-与gpt-claude的横向对比" tabindex="-1">7.2 与GPT/Claude的横向对比 <a class="header-anchor" href="#_7-2-与gpt-claude的横向对比" aria-label="Permalink to &quot;7.2 与GPT/Claude的横向对比&quot;">​</a></h3><p>Gemini vs GPT vs Claude 的关键差异化对比：</p><table tabindex="0"><thead><tr><th>维度</th><th>Gemini</th><th>GPT-5.5</th><th>Claude Opus 4.7</th></tr></thead><tbody><tr><td>推理速度（tokens/秒）</td><td>289（3.5 Flash）</td><td>~72</td><td>~72</td></tr><tr><td>上下文窗口（max）</td><td>200万</td><td>100万</td><td>100万</td></tr><tr><td>原生多模态</td><td>是（Omni视频级）</td><td>有限</td><td>有限</td></tr><tr><td>第三方评测准确性</td><td>信息准确性第一</td><td>创造力优先</td><td>安全性优先</td></tr><tr><td>Agent能力侧重</td><td>工作流编排</td><td>综合能力</td><td>代码工程</td></tr><tr><td>全栈整合</td><td>搜索/安卓/Workspace</td><td>ChatGPT生态</td><td>企业安全</td></tr></tbody></table><p>2026年的一次独立对比测试中，Gemini在信息准确性和实用性建议方面优于ChatGPT，以4比3的比分领先，而ChatGPT在创造性和紧急情景模拟中表现更好。从发展方向上看，Gemini的核心优势在于信息准确性、超长上下文处理和与谷歌全生态的深度整合。</p><h3 id="_7-3-主要型号速度对比" tabindex="-1">7.3 主要型号速度对比 <a class="header-anchor" href="#_7-3-主要型号速度对比" aria-label="Permalink to &quot;7.3 主要型号速度对比&quot;">​</a></h3><p>在实际运行效率方面，各主力型号对比：</p><table tabindex="0"><thead><tr><th>模型</th><th>首Token延迟</th><th>吞吐量</th><th>备注</th></tr></thead><tbody><tr><td>Gemini 3.5 Flash</td><td>—</td><td>289 tokens/秒</td><td>输出速度</td></tr><tr><td>Gemini 3.1 Flash-Lite</td><td>2.5倍速度提升</td><td>363 tokens/秒</td><td>吞吐量旗舰</td></tr><tr><td>Gemini 3.1 Pro</td><td>中等</td><td>—</td><td>推理优先</td></tr><tr><td>GPT-5.5</td><td>—</td><td>~72 tokens/秒</td><td>约4倍差距</td></tr><tr><td>Claude Opus 4.7</td><td>—</td><td>~72 tokens/秒</td><td>约4倍差距</td></tr></tbody></table><h2 id="八、局限性与挑战" tabindex="-1">八、局限性与挑战 <a class="header-anchor" href="#八、局限性与挑战" aria-label="Permalink to &quot;八、局限性与挑战&quot;">​</a></h2><h3 id="_8-1-安全与深度伪造风险" tabindex="-1">8.1 安全与深度伪造风险 <a class="header-anchor" href="#_8-1-安全与深度伪造风险" aria-label="Permalink to &quot;8.1 安全与深度伪造风险&quot;">​</a></h3><p>Gemini的多模态生成能力，特别是Omni Flash的视频生成与编辑能力，引发了深度伪造风险。虽然谷歌在Omni生成内容中均带有SynthID数字水印，并新增了内容凭证验证功能帮助用户识别AI生成内容，但第三方开发者报告显示——在没有这些保护机制的情况下，模型仍可能被用于传播虚假信息或制造误导性内容。谷歌面临“开放能力vs安全控制”之间的平衡难题。</p><h3 id="_8-2-硬件依赖与成本压力" tabindex="-1">8.2 硬件依赖与成本压力 <a class="header-anchor" href="#_8-2-硬件依赖与成本压力" aria-label="Permalink to &quot;8.2 硬件依赖与成本压力&quot;">​</a></h3><p>谷歌的垂直整合战略也使其高度依赖自研TPU的性能表现。虽然第八代TPU提供了强大的算力支撑，但大型模型训练和推理的计算成本依然居高不下。Gemini 3.5 Flash的运行成本比前代版本高出5倍以上。在对成本敏感的开发者市场上，这可能会影响Gemini的普及率。</p><h3 id="_8-3-隐私与数据合规" tabindex="-1">8.3 隐私与数据合规 <a class="header-anchor" href="#_8-3-隐私与数据合规" aria-label="Permalink to &quot;8.3 隐私与数据合规&quot;">​</a></h3><p>Gemini与谷歌全生态深度集成意味着大量个人数据在模型与应用间流转，引发用户隐私和数据安全担忧。Gemini Spark智能体能够7×24小时在云端运行并访问用户的Gmail、Docs、Calendar等私人数据，对数据访问权限的控制和用户知情权构成了挑战。此外，随着欧盟AI法案等全球监管法规的陆续落地，Gemini面临跨区域合规的复杂性增加。</p><h3 id="_8-4-模型稳定性与可靠性" tabindex="-1">8.4 模型稳定性与可靠性 <a class="header-anchor" href="#_8-4-模型稳定性与可靠性" aria-label="Permalink to &quot;8.4 模型稳定性与可靠性&quot;">​</a></h3><p>从会后评价来看，Gemini Omni在部分评测中“表现不如预期”，稳定性和大规模应用适应性仍有待验证。Gemini 3.5 Flash虽已作为默认模型上线，但开发者测试反馈其稳定性有待提升。谷歌在2.5 Pro阶段曾公开承认模型存在“性能短暂下滑”的问题并进行优化。</p><h3 id="_8-5-竞争压力与成本权衡" tabindex="-1">8.5 竞争压力与成本权衡 <a class="header-anchor" href="#_8-5-竞争压力与成本权衡" aria-label="Permalink to &quot;8.5 竞争压力与成本权衡&quot;">​</a></h3><p>随着OpenAI和Anthropic在代码工程等领域的持续突破，Gemini在特定基准上逐渐面临压力。2026年4月发布的新基准DeepSWE中，Gemini 3.1 Pro得分54%±5%，与GPT-5.5（70%）存在差距。谷歌正在面对的竞争已不再是“谁最聪明”，而是谁更快、更便宜、更适合大规模部署——在延迟和成本的重要性迅速提升的市场环境中，谷歌仍需在性能、速度和成本之间寻找最优权衡。</p><h3 id="_8-6-对齐与可解释性" tabindex="-1">8.6 对齐与可解释性 <a class="header-anchor" href="#_8-6-对齐与可解释性" aria-label="Permalink to &quot;8.6 对齐与可解释性&quot;">​</a></h3><p>虽然Gemini 2.0 Flash Thinking已开放了推理链可视化功能，但对于更深层次的模型行为——为何做出特定判断、如何受训练数据偏见影响——仍缺乏全面的可解释性解决方案。同时，Gemini的多模态特性使传统上仅针对文本的对齐方法面临新的适用性挑战。</p><h2 id="九、未来展望" tabindex="-1">九、未来展望 <a class="header-anchor" href="#九、未来展望" aria-label="Permalink to &quot;九、未来展望&quot;">​</a></h2><h3 id="_9-1-gemini-4-0-原生多模态一体化大脑" tabindex="-1">9.1 Gemini 4.0：原生多模态一体化大脑 <a class="header-anchor" href="#_9-1-gemini-4-0-原生多模态一体化大脑" aria-label="Permalink to &quot;9.1 Gemini 4.0：原生多模态一体化大脑&quot;">​</a></h3><p>I/O 2026大会前曾有传闻将发布Gemini 4.0，最终谷歌展示了Omni系列而非正式推出4.0。按照此前规划，Gemini 4.0将实现原生多模态一体化处理——无需外挂工具即可同步解析文本、图像、音频、视频、屏幕信息、空间位置数据。谷歌2026年的旗舰底座目标是在逻辑推理能力上实现跨越式提升，全方位对标GPT-5.5。业界推测，Gemini 4.0有可能在2026年秋季或2027年初正式亮相。</p><h3 id="_9-2-智能体生态的全面铺开" tabindex="-1">9.2 智能体生态的全面铺开 <a class="header-anchor" href="#_9-2-智能体生态的全面铺开" aria-label="Permalink to &quot;9.2 智能体生态的全面铺开&quot;">​</a></h3><p>Gemini Spark被视为谷歌打造个人智能体的第一步，未来将与Gmail、Docs、Calendar等Workspace工具实现更深度的无缝协作。Antigravity 2.0的定位明确——谷歌不仅要推出智能体，更要提供一个 <strong>“智能体操作系统”</strong> ，让用户可以创建、管理和编排多个AI智能体集群。从展示中93个AI智能体在12小时内从零构建操作系统内核的能力来看，多智能体协作的潜力已经得到初步验证。未来Gemini智能体的工作范围将从个人办公辅助，拓展至复杂的企业级自动化和全流程管理。</p><h3 id="_9-3-全模态交互的深化" tabindex="-1">9.3 全模态交互的深化 <a class="header-anchor" href="#_9-3-全模态交互的深化" aria-label="Permalink to &quot;9.3 全模态交互的深化&quot;">​</a></h3><p>随着Omni系列的推出，Gemini正朝着“理解物理世界”的方向演进——从简单的像素级生成，到理解动能、重力等物理规律的“世界模型”。谷歌将这一方向作为未来Gemini发展的重要战略，目标是让AI真正理解我们生活的物理世界，而不仅仅是处理屏幕上的信息。现场演示中员工用一句“用黏土动画解释蛋白质折叠”生成符合物理规律的视频，预示着未来教育、设计、科学可视化等多个领域的应用潜力。</p><h3 id="_9-4-成本效率的持续优化" tabindex="-1">9.4 成本效率的持续优化 <a class="header-anchor" href="#_9-4-成本效率的持续优化" aria-label="Permalink to &quot;9.4 成本效率的持续优化&quot;">​</a></h3><p>谷歌在I/O大会上发布100美元/月的基础版Ultra开发者计划，并将最高阶Ultra旗舰版月费从250美元下调至200美元，显示出在高阶市场中以性价比吸引开发者和企业的战略。同时，谷歌正在通过自研TPU芯片的超大规模算力集群不断降低单次推理成本。未来，Gemini 4.0预计将进一步完善计算效率，使原生多模态、超长上下文、智能体工作流的能力在一个平台上实现经济可行的规模化部署。</p>',123)])])}const g=i(r,[["render",d]]);export{p as __pageData,g as default};
